import{_ as a,o as t,c as r,ag as o}from"./chunks/framework.CrXGS008.js";const u=JSON.parse('{"title":"Features","description":"","frontmatter":{},"headers":[],"relativePath":"en/features.md","filePath":"en/features.md","lastUpdated":null}'),s={name:"en/features.md"};function n(i,e,d,l,c,p){return t(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="features" tabindex="-1">Features <a class="header-anchor" href="#features" aria-label="Permalink to &quot;Features&quot;">​</a></h1><h2 id="layout-and-appearance" tabindex="-1">Layout and appearance <a class="header-anchor" href="#layout-and-appearance" aria-label="Permalink to &quot;Layout and appearance&quot;">​</a></h2><p>Use daily cards, compact inspection tables or mobile layouts. The palette button opens theme settings. Card transparency changes the background alpha while text and charts remain opaque. Personal preferences are saved in your browser; administrators can save site defaults.</p><p>Image/video backgrounds support ordered, random and hold modes. Server-side upload and URL import require the companion service. A public media URL is required; share pages and authenticated downloads are not direct media links.</p><h2 id="network-history-and-comparisons" tabindex="-1">Network history and comparisons <a class="header-anchor" href="#network-history-and-comparisons" aria-label="Permalink to &quot;Network history and comparisons&quot;">​</a></h2><p>Hover or select a history cell to inspect latency and packet loss. Compare up to four nodes with an explicit common time window. Automatic home summaries prefer assigned TCP monitoring tasks; the selected scope is shown on each card.</p><p>Nearby targets can genuinely return 1 ms. The “last received” indicator is report age, not a latency measurement.</p><h2 id="global-globe" tabindex="-1">Global globe <a class="header-anchor" href="#global-globe" aria-label="Permalink to &quot;Global globe&quot;">​</a></h2><p>Drag the globe, use arrow keys, or click a flag to select a node in the adjacent list. Coordinates are approximate region centers, not precise data-center locations. The home regions card opens the globe in a modal.</p><h2 id="reports" tabindex="-1">Reports <a class="header-anchor" href="#reports" aria-label="Permalink to &quot;Reports&quot;">​</a></h2><p>View free and paid assets, expiry timelines and traffic totals. Dates more than ten years ahead display as long-term. Exchange rates are the latest published reference values with source dates and cache status. They are not live trading quotes.</p><p>History coverage and precision depend on your Komari backend. Missing data is not converted into invented samples or zero traffic.</p>',12)])])}const m=a(s,[["render",n]]);export{u as __pageData,m as default};
